import re
from enum import Enum

from taf.nms.netact.exceptions import MandatoryAttributesNotDefined


class MoClass:
    IP_VERSIONS = Enum('ip_version', {'0': 'IPV4', '1': 'IPV6'})  # type: ignore[misc]
    SECURITY_MODES = Enum('security_mode', {'0': 'NO TLS', '1': 'TLS'})  # type: ignore[misc]
    MO_CLASS: str
    DEFAULT_ADAPTATION: str

    def __init_subclass__(cls, **kwargs):
        super().__init_subclass__(**kwargs)
        required_attributes = [
            'MO_CLASS',
            'DEFAULT_ADAPTATION'
        ]
        missing_attributes = [a for a in required_attributes if not hasattr(cls, a)]
        if missing_attributes:
            raise AttributeError(f"{cls.__name__!r} must have {', '.join(missing_attributes)} attribute(s)")

    def __init__(self, mo_release, mr, address, username, dist_name, presentation_name=None,
                 http_port='8080', https_port='8443', ip_version='IPV4', security_mode='no TLS'):
        self.mo_release = mo_release.upper()
        self.mr = mr
        self.address = address
        self.username = username
        self.dist_name = dist_name
        self.presentation_name = self._convert_optional_parameter(presentation_name)
        self.http_port = http_port
        self.https_port = https_port
        self.ip_version = self.IP_VERSIONS(ip_version.upper()).name
        self.security_mode = self.SECURITY_MODES(security_mode.upper()).name

    @staticmethod
    def _convert_optional_parameter(value):
        if not value:
            return 'null'
        elif isinstance(value, list):
            return ','.join(value)
        else:
            return value

    @property
    def adaptation(self):
        return self.DEFAULT_ADAPTATION

    @property
    def args(self):
        return (
            self.adaptation,
            self.mo_release,
            self.MO_CLASS,
            self.username
        )


class MRBTSv1(MoClass):
    MO_CLASS = 'MRBTS'
    DEFAULT_ADAPTATION = 'com.nokia.srbts'
    ADAPTATION_MAPPING = {
        'FL': 'NOKLTE',
        'TL': 'NOKLTE',
        '5G': 'com.nokia.nrbts',
        'VDU': 'com.nokia.nrbts',
        'VCU': 'com.nokia.nrbts'
    }
    DEFAULT_IDS_ORDER = ('#1#', '#2#', '#3#', '#8#', '#4#', '#5#', '#9#', '#6#', '#7#')
    IDS_ORDER_MAPPING = {
        'com.nokia.nrbts': ('#4#', '#1#', '#5#', '#3#', '#6#', '#7#', '#8#', '#2#')
    }

    def __init__(self, mo_release, mr, address, username, dist_name, presentation_name=None,
                 http_port='8080', https_port='8443', ip_version='IPV4', security_mode='no TLS',
                 mrbts_em_address=None):
        super().__init__(
            mo_release, mr, address, username, dist_name, presentation_name,
            http_port, https_port, ip_version, security_mode
        )
        self.mrbts_em_address = mrbts_em_address

    @property
    def adaptation(self):
        mo_release_prefix = re.search('^FL|^TL|^5G|VDU$|VCU$|$', self.mo_release).group()
        return self.ADAPTATION_MAPPING.get(mo_release_prefix, self.DEFAULT_ADAPTATION)

    @property
    def additional_args(self):
        return (
            self.mr,
            self.address,
            self.dist_name,
            self.presentation_name,
            self.http_port,
            self.https_port,
            self.ip_version,
            self.security_mode,
            self.mrbts_em_address
        )

    @property
    def kwargs(self):
        ids_order = self.IDS_ORDER_MAPPING.get(self.adaptation, self.DEFAULT_IDS_ORDER)
        return dict(zip(ids_order, self.additional_args))


class MRBTSv2(MoClass):
    MO_CLASS = 'MRBTS'
    DEFAULT_ADAPTATION = 'com.nokia.srbts'
    CERTIFICATE_TYPE = Enum('certificate_type', {  # type: ignore[misc]
        'Already installed': 'ALREADY INSTALLED',
        'Install via CMP': 'INSTALL VIA CMP'})

    def __init__(self, mo_release, mr, address, username, dist_name, presentation_name=None,
                 http_port='8080', https_port='8443', ip_version='IPV4', security_mode='no TLS',
                 certificate_type='Already Installed', cmp=None):

        super().__init__(
            mo_release, mr, address, username, dist_name, presentation_name,
            http_port, https_port, ip_version, security_mode
        )

        self.presentation_name = presentation_name or ''
        self.certificate_type = self.CERTIFICATE_TYPE(certificate_type.upper()).name if self.security_mode == '1' else ''
        self.cmp = cmp
        if self.certificate_type == "Install via CMP":
            self._validate_certificate_settings(cmp)

    @property
    def kwargs(self):
        return {
            "version": self.mo_release,
            "MR": self.mr,
            "agentAddress": self.address,
            "MO_DN": self.dist_name,
            "MO_Name": self.presentation_name,
            "HTTP_port": self.http_port,
            "HTTPS_port": self.https_port,
            "IP_version": self.ip_version,
            "NE3SWSSecurityMode": self.security_mode,
            "certificateType": self.certificate_type,
            "cmp": self.cmp
        }

    @staticmethod
    def _validate_certificate_settings(cmp):
        mandatory_attributes = {"CMPserverHost", "CMPserverPort", "CMPserverPath", "CAName"}
        missing_attributes = mandatory_attributes.difference(cmp)
        if missing_attributes:
            exc_msg = f"{', '.join(missing_attributes)} attribute(s) of cmp parameter are not defined."
            raise MandatoryAttributesNotDefined(exc_msg)


class MRBTSv2CPRIGW(MoClass):
    MO_CLASS = 'MRBTS'
    DEFAULT_ADAPTATION = 'com.nokia.cprigw'

    def __init__(self, mo_release, mr, address, username, dist_name, presentation_name=None,
                 http_port='8080', https_port='8443', ip_version='IPV4', security_mode='no TLS'):
        super().__init__(
            mo_release, mr, address, username, dist_name, presentation_name,
            http_port, https_port, ip_version, security_mode
        )

        self.presentation_name = presentation_name or ''

    @property
    def kwargs(self):
        return {
            "version": self.mo_release,
            "MR": self.mr,
            "Host_Name": self.address,
            "FQDN": self.dist_name,
            "NE_Name": self.presentation_name,
            "Http_Port": self.http_port,
            "Https_Port": self.https_port,
            "Tls": self.security_mode,
            "Ip_Version": self.ip_version
        }


