class NADCM(MoClass):
    MO_CLASS = 'NADCM'
    DEFAULT_ADAPTATION = 'com.nokia.nadcm'
    REINTEGRATIONS = Enum('reintegration', {'YES': 'YES', 'NO': 'NO'})  # type: ignore[misc]

    def __init__(self, mo_release, mr, address, username, dist_name, ftp_path,
                 presentation_name=None, ha_nadcm_ips=None, subnet_mask=24, reintegration='NO',
                 https_port='443', snmp_port='7161', sftp_port='7122'):
        super().__init__(
            mo_release, mr, address, username, dist_name, presentation_name, https_port=https_port
        )
        self.ha_nadcm_ips = self._convert_optional_parameter(ha_nadcm_ips)
        self.subnet_mask = subnet_mask
        self.reintegration = self.REINTEGRATIONS(reintegration.upper()).name
        self.snmp_port = snmp_port
        self.sftp_port = sftp_port
        self.ftp_path = ftp_path

    @property
    def kwargs(self):
        return {
            '#1#': self.mr,
            '#2#': self.address,
            '#3#': self.dist_name,
            '#4#': self.presentation_name,
            '#5#': self.https_port,
            '#6#': self.snmp_port,
            '#9#': self.subnet_mask,
            '#10#': self.reintegration,
            '#11#': self.sftp_port,
            '#12#': self.ha_nadcm_ips,
            '#FTP_Path#': self.ftp_path,
        }


class MoClassFactory:
    SUPPORTED = {
        'ASI': ASI,
        'FHGW': FHGW,
        'NADCM': NADCM
    }

    @classmethod
    def get_mo_class(cls, name):
        mo_class = cls.SUPPORTED.get(name, None)
        if mo_class:
            return mo_class
        exc_msg = f'{name!r} MO Class is not supported!'
        raise NotImplementedError(exc_msg)
